import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic(); // ключ берётся из ANTHROPIC_API_KEY
const MODEL = "claude-sonnet-5";
const WINDOW = 1_000_000; // окно своей модели сверяй с доками

// Сколько места осталось на ответ и какой max_tokens отправить
function planMaxTokens(inputTokens: number, wanted: number, margin = 1_000): number {
  const left = WINDOW - inputTokens;
  if (left <= margin) {
    // API ответит 400 invalid_request_error: уменьшай вход, а не max_tokens
    throw new Error("prompt is too long: " + inputTokens + " tokens");
  }
  return Math.min(wanted, left - margin);
}

async function ask(messages: Anthropic.MessageParam[]) {
  // 1. До вызова: считаем вход (бесплатно, это оценка)
  const { input_tokens } = await client.messages.countTokens({ model: MODEL, messages });

  // 2. Сам вызов с max_tokens, урезанным до остатка окна
  const msg = await client.messages.create({
    model: MODEL,
    max_tokens: planMaxTokens(input_tokens, 8_000),
    messages,
  });

  // 3. После вызова: HTTP 200 не значит «ответ закончен»
  const truncated =
    msg.stop_reason === "max_tokens" ||
    msg.stop_reason === "model_context_window_exceeded";
  console.log(msg.stop_reason, msg.usage.input_tokens, msg.usage.output_tokens);
  return { msg, truncated };
}

